def count_long_subarray(A):
    n = len(A)
    current = 1   # length of longest increasing subarray ending at A[i - 1]
    length = 1    # length of longest increasing subarray in A[:i]
    count = 1     # number of longest increasing subarrays in A[:i]
    for i in range(1, n):
        if A[i - 1] < A[i]:
            current = current + 1
        else:
            current = 1
        if current == length:
            count = count + 1
        elif current > length:
            length = current
            count = 1
    return count
